// ─── Helpers ──────────────────────────────────────────────────────────────────

function randomLetter(lang: string): string {
  const alpha = lang === 'pt' ? ALPHABET_PT : ALPHABET_EN;
  return alpha[Math.floor(Math.random() * alpha.length)];
}

function getHints(catId: string, letter: string, lang: string): string[] {
  const catHints = HINTS[catId];
  if (!catHints) return [];
  const letterHints = catHints[letter];
  if (!letterHints) return [];
  return lang === 'pt' ? letterHints.pt : letterHints.en;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function StopGame({ lang }: StopGameProps) {
  const [phase, setPhase] = useState<Phase>('setup');
  const [selectedCats, setSelectedCats] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem(LS_KEY);
      if (saved) {
        const parsed = JSON.parse(saved) as string[];
        return Array.isArray(parsed) ? parsed : [];
      }
    } catch {}
    return ['cities', 'animals', 'names', 'fruits', 'colors'];
  });
  const [chosenLetter, setChosenLetter] = useState('A');
  const [displayLetter, setDisplayLetter] = useState('A');
  const [rouletteState, setRouletteState] = useState<'spinning' | 'landing' | 'landed'>('spinning');
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [openHints, setOpenHints] = useState<Record<string, boolean>>({});
  const [timerOption, setTimerOption] = useState<TimerOption>(() => {
    try {
      const saved = localStorage.getItem(LS_TIMER_KEY);
      if (saved) {
        const n = Number(saved) as TimerOption;
        return TIMER_OPTIONS.includes(n) ? n : 60;
      }
    } catch {}
    return 60;
  });
  const [timeLeft, setTimeLeft] = useState(0);
  const [timerRunning, setTimerRunning] = useState(false);
  const [timeUp, setTimeUp] = useState(false);
  const [round, setRound] = useState(0);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const rouletteRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const alphaRef = useRef(lang === 'pt' ? ALPHABET_PT : ALPHABET_EN);

  // Update alphabet ref when lang changes
  useEffect(() => {
    alphaRef.current = lang === 'pt' ? ALPHABET_PT : ALPHABET_EN;
  }, [lang]);

  // Persist selections
  useEffect(() => {
    localStorage.setItem(LS_KEY, JSON.stringify(selectedCats));
  }, [selectedCats]);

  useEffect(() => {
    localStorage.setItem(LS_TIMER_KEY, String(timerOption));
  }, [timerOption]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      if (rouletteRef.current) clearInterval(rouletteRef.current);
    };
  }, []);

  const toggleCategory = useCallback((id: string) => {
    setSelectedCats(prev =>
      prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]
    );
  }, []);

  // Speak a letter using Web Speech API
  const speakLetter = useCallback((letter: string) => {
    try {
      const utterance = new SpeechSynthesisUtterance(letter);
      utterance.lang = lang === 'pt' ? 'pt-PT' : 'en-US';
      utterance.rate = 0.8;
      utterance.pitch = 1.2;
      utterance.volume = 1;
      window.speechSynthesis.cancel();
      window.speechSynthesis.speak(utterance);
    } catch {
      // Speech API not supported — ignore silently
    }
  }, [lang]);

  const startRoulette = useCallback(() => {
    setPhase('roulette');
    setRouletteState('spinning');
    const alpha = alphaRef.current;
    let idx = Math.floor(Math.random() * alpha.length);

    if (rouletteRef.current) clearInterval(rouletteRef.current);

    // Letters cycle fast until user presses STOP
    rouletteRef.current = setInterval(() => {
      idx = (idx + 1) % alpha.length;
      setDisplayLetter(alpha[idx]);
    }, 70);
  }, []);

  const handleStop = useCallback(() => {
    if (rouletteState !== 'spinning') return;
    if (rouletteRef.current) clearInterval(rouletteRef.current);

    // Pick the letter that's currently displayed (feels fair — it's what you "stopped" on)
    const final = randomLetter(lang);
    setChosenLetter(final);
    setDisplayLetter(final);
    setRouletteState('landing');
    speakLetter(final);

    setTimeout(() => {
      setRouletteState('landed');
      setTimeout(() => {
        setPhase('playing');
        setAnswers({});
        setOpenHints({});
        setTimeUp(false);
        if (timerOption > 0) {
          setTimeLeft(timerOption);
          setTimerRunning(true);
        }
      }, 1500);
    }, 400);
  }, [lang, timerOption, rouletteState, speakLetter]);

  // Timer countdown
  useEffect(() => {
    if (!timerRunning || timerOption === 0) return;
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          setTimerRunning(false);
          setTimeUp(true);
          setPhase('results');
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [timerRunning, timerOption]);

  const handleEndRound = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);
    setTimerRunning(false);
    setPhase('results');
    setRound(r => r + 1);
  }, []);

  const handleNewLetter = useCallback(() => {
    setAnswers({});
    setOpenHints({});
    setTimeUp(false);
    startRoulette();
  }, [startRoulette]);

  const handleChangeCategories = useCallback(() => {
    setPhase('setup');
    setAnswers({});
    setOpenHints({});
    setTimeUp(false);
    if (timerRef.current) clearInterval(timerRef.current);
    setTimerRunning(false);
  }, []);

  const toggleHint = useCallback((catId: string) => {
    setOpenHints(prev => ({ ...prev, [catId]: !prev[catId] }));
  }, []);

  const activeCats = CATEGORIES.filter(c => selectedCats.includes(c.id));
  const timerPct = timerOption > 0 ? timeLeft / timerOption : 1;

  // ── Touch refs for STOP button ──
  const stopTouchStart = useRef<{ x: number; y: number } | null>(null);
  const stopSuppressClick = useRef(false);

  // ─────────────────────────────────────────────────────────────────────────────
  // Render
  // ─────────────────────────────────────────────────────────────────────────────

  return (
    <Wrapper>
      <PageTitle>{t('title', lang)}</PageTitle>

      {/* ── SETUP ── */}
      {phase === 'setup' && (
        <>
          <Subtitle>{t('chooseCategories', lang)}</Subtitle>
          <SelectionHeader>
            <Counter>
              <CountBadge ok={selectedCats.length >= 3}>{selectedCats.length}</CountBadge>
              {' '}{t('selected', lang)}
              {selectedCats.length < 3 && (
                <span style={{ marginLeft: theme.spacing.sm, color: '#f0a202', fontSize: theme.typography.fontSizeSm }}>
                  — {t('minCategories', lang)}
                </span>
              )}
            </Counter>
          </SelectionHeader>
          <CategoriesGrid>
            {CATEGORIES.map(cat => {
              const isSelected = selectedCats.includes(cat.id);
              return (
                <CategoryCard
                  key={cat.id}
                  selected={isSelected}
                  onClick={() => toggleCategory(cat.id)}
                  type="button"
                  aria-pressed={isSelected}
                >
                  {isSelected && <CheckMark>✓</CheckMark>}
                  <CategoryEmoji>{cat.icon}</CategoryEmoji>
                  <CategoryName>{lang === 'pt' ? cat.label.pt : cat.label.en}</CategoryName>
                </CategoryCard>
              );
            })}
          </CategoriesGrid>

          <div style={{ marginTop: theme.spacing.lg, width: '100%', maxWidth: '720px' }}>
            <TimerRow>
              <TimerLabel>{t('timer', lang)}:</TimerLabel>
              {TIMER_OPTIONS.map(opt => (
                <TimerOption
                  key={opt}
                  active={timerOption === opt}
                  onClick={() => setTimerOption(opt)}
                  type="button"
                >
                  {opt === 0 ? t('noTimer', lang) : `${opt}${t('seconds', lang)}`}
                </TimerOption>
              ))}
            </TimerRow>
          </div>

          <StartButton
            disabled={selectedCats.length < 3}
            onClick={selectedCats.length >= 3 ? startRoulette : undefined}
            type="button"
          >
            {t('startGame', lang)}
          </StartButton>
        </>
      )}

      {/* ── ROULETTE ── */}
      {phase === 'roulette' && (
        <RouletteStage>
          <LetterCircle landing={rouletteState === 'landing'} landed={rouletteState === 'landed'}>
            {displayLetter}
          </LetterCircle>
          {rouletteState === 'spinning' && (
            <>
              <RouletteLabel>{t('spinning', lang)}</RouletteLabel>
              <BigStopBtn
                onTouchStart={e => { stopTouchStart.current = { x: e.touches[0].clientX, y: e.touches[0].clientY }; }}
                onTouchEnd={e => {
                  if (!stopTouchStart.current) return;
                  const dx = Math.abs(e.changedTouches[0].clientX - stopTouchStart.current.x);
                  const dy = Math.abs(e.changedTouches[0].clientY - stopTouchStart.current.y);
                  stopTouchStart.current = null;
                  if (dx > 8 || dy > 8) return;
                  stopSuppressClick.current = true;
                  handleStop();
                }}
                onClick={() => {
                  if (stopSuppressClick.current) { stopSuppressClick.current = false; return; }
                  handleStop();
                }}
              >
                STOP!
              </BigStopBtn>
            </>
          )}
          {(rouletteState === 'landing' || rouletteState === 'landed') && (
            <LandedText>
              {t('got', lang)} <strong>&ldquo;{chosenLetter}&rdquo;</strong>!
              <br />
              <span style={{ fontSize: '1rem', fontWeight: 400, color: theme.colors.mainTextMuted }}>
                {t('thinkFast', lang)}
              </span>
            </LandedText>
          )}
        </RouletteStage>
      )}

      {/* ── PLAYING ── */}
      {phase === 'playing' && (
        <PlayingWrapper>
          <LetterBanner>
            <LetterBadge>{chosenLetter}</LetterBadge>
            <div>
              <div style={{ fontSize: theme.typography.fontSizeLg, fontWeight: 700, color: theme.colors.mainText }}>
                {t('got', lang)} &ldquo;{chosenLetter}&rdquo;
              </div>
              {round > 0 && (
                <div style={{ fontSize: theme.typography.fontSizeSm, color: theme.colors.mainTextMuted }}>
                  {t('roundCount', lang)} {round + 1}
                </div>
              )}
            </div>
          </LetterBanner>

          {timerOption > 0 && (
            <TimerRow>
              <TimerDisplay pct={timerPct} />
              <TimerCountdown pct={timerPct}>{timeLeft}{t('seconds', lang)}</TimerCountdown>
            </TimerRow>
          )}

          {activeCats.map(cat => {
            const hints = getHints(cat.id, chosenLetter, lang);
            const hintOpen = openHints[cat.id] ?? false;
            return (
              <CategoryAnswerCard key={cat.id}>
                <CardHeader>
                  <CardTitle>
                    <span>{cat.icon}</span>
                    {lang === 'pt' ? cat.label.pt : cat.label.en}
                  </CardTitle>
                  <HintToggle
                    onClick={() => toggleHint(cat.id)}
                    type="button"
                  >
                    {hintOpen ? t('hideHints', lang) : t('showHints', lang)}
                  </HintToggle>
                </CardHeader>
                <AnswerInput
                  value={answers[cat.id] ?? ''}
                  onChange={e => setAnswers(prev => ({ ...prev, [cat.id]: e.target.value }))}
                  placeholder={t('typeAnswer', lang)}
                  spellCheck={false}
                  autoCapitalize="off"
                />
                {hintOpen && (
                  <HintsBox>
                    <HintsLabel>{t('suggestions', lang)}</HintsLabel>
                    {hints.length > 0 ? (
                      <HintsList>
                        {hints.map((h, i) => (
                          <HintChip key={i}>{h}</HintChip>
                        ))}
                      </HintsList>
                    ) : (
                      <NoHintsText>{t('noHints', lang)}</NoHintsText>
                    )}
                  </HintsBox>
                )}
              </CategoryAnswerCard>
            );
          })}

          <StopButton
            type="button"
            onTouchStart={e => {
              stopTouchStart.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            }}
            onTouchEnd={e => {
              if (!stopTouchStart.current) return;
              const dx = Math.abs(e.changedTouches[0].clientX - stopTouchStart.current.x);
              const dy = Math.abs(e.changedTouches[0].clientY - stopTouchStart.current.y);
              stopTouchStart.current = null;
              if (dx > 8 || dy > 8) return;
              stopSuppressClick.current = true;
              handleEndRound();
            }}
            onClick={() => {
              if (stopSuppressClick.current) { stopSuppressClick.current = false; return; }
              handleEndRound();
            }}
          >
            {t('stopBtn', lang)}
          </StopButton>
        </PlayingWrapper>
      )}

      {/* ── RESULTS ── */}
      {phase === 'results' && (
        <ResultsWrapper>
          <ResultsHeader>
            <ResultsTitle>
              {timeUp ? t('timeUp', lang) : t('roundOver', lang)}
            </ResultsTitle>
            <ResultsSubtitle>
              {t('got', lang)} &ldquo;{chosenLetter}&rdquo;
              {round > 0 && ` · ${t('roundCount', lang)} ${round + 1}`}
            </ResultsSubtitle>
          </ResultsHeader>

          {activeCats.map(cat => (
            <ResultCard key={cat.id}>
              <ResultCategoryName>
                <span>{cat.icon}</span>
                {lang === 'pt' ? cat.label.pt : cat.label.en}
              </ResultCategoryName>
              <ResultAnswer>
                {answers[cat.id] || (
                  <span style={{ color: theme.colors.mainTextMuted, fontStyle: 'italic' }}>—</span>
                )}
              </ResultAnswer>
            </ResultCard>
          ))}

          <ActionsRow>
            <ActionButton type="button" onClick={handleNewLetter}>
              {t('newLetter', lang)}
            </ActionButton>
            <ActionButton type="button" variant="secondary" onClick={handleChangeCategories}>
              {t('changeCategories', lang)}
            </ActionButton>
          </ActionsRow>
        </ResultsWrapper>
      )}
    </Wrapper>
  );
}
