const POINTS_PER_LEVEL = 50;

interface LevelInfo { emoji: string; pt: string; en: string }
const LEVELS: LevelInfo[] = [
  { emoji: '🌱', pt: 'Recruta',    en: 'Recruit'    }, // 1
  { emoji: '🧭', pt: 'Explorador', en: 'Explorer'   }, // 2
  { emoji: '⚔️', pt: 'Aventureiro', en: 'Adventurer' }, // 3
  { emoji: '🦸', pt: 'Herói',      en: 'Hero'       }, // 4
  { emoji: '🏆', pt: 'Campeão',    en: 'Champion'   }, // 5
  { emoji: '🌟', pt: 'Lenda',      en: 'Legend'     }, // 6+
];

function getLevelIndex(totalPoints: number): number {
  const lvl = Math.floor(totalPoints / POINTS_PER_LEVEL);
  return Math.min(lvl, LEVELS.length - 1);
}

function getLevelNumber(totalPoints: number): number {
  return Math.floor(totalPoints / POINTS_PER_LEVEL) + 1;
}

function getXpProgress(totalPoints: number): number {
  return ((totalPoints % POINTS_PER_LEVEL) / POINTS_PER_LEVEL) * 100;
}

function todayISO(): string {
  return new Date().toISOString().slice(0, 10);
}

function loadState(): PersistedState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return JSON.parse(raw) as PersistedState;
  } catch {
    // ignore
  }
  return {
    totalPoints: 0,
    totalMissionsCompleted: 0,
    completedToday: [],
    streakDays: [],
    lastResetDate: todayISO(),
  };
}

function saveState(state: PersistedState): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // ignore
  }
}

function computeStreak(streakDays: string[]): number {
  if (streakDays.length === 0) return 0;
  const sorted = [...new Set(streakDays)].sort().reverse();
  const today = todayISO();
  let streak = 0;
  let expected = today;
  for (const day of sorted) {
    if (day === expected) {
      streak++;
      const d = new Date(expected);
      d.setDate(d.getDate() - 1);
      expected = d.toISOString().slice(0, 10);
    } else {
      break;
    }
  }
  return streak;
}

