// ─── Component ────────────────────────────────────────────────────────────────

export function MissionManager({ lang, onBack }: MissionManagerProps) {
  const pt = lang === 'pt';

  const [state, setState] = useState<PersistedState>(() => {
    const loaded = loadState();
    // Auto-reset if last reset was a different day (new calendar day)
    const today = todayISO();
    if (loaded.lastResetDate !== today) {
      return {
        ...loaded,
        completedToday: [],
        lastResetDate: today,
      };
    }
    return loaded;
  });

  const [flashingIds, setFlashingIds] = useState<Set<string>>(new Set());
  const [newlyCompletedIds, setNewlyCompletedIds] = useState<Set<string>>(new Set());
  const [floatingPoints, setFloatingPoints] = useState<FloatingPoint[]>([]);
  const [levelUpInfo, setLevelUpInfo] = useState<LevelInfo | null>(null);
  const [levelUpExiting, setLevelUpExiting] = useState(false);
  const [xpShimmer, setXpShimmer] = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);
  const floatingIdRef = useRef(0);
  const touchStartRef = useRef<{ x: number; y: number } | null>(null);
  const suppressClickRef = useRef<Record<string, boolean>>({});

  // Persist on every state change
  useEffect(() => {
    saveState(state);
  }, [state]);

  const previousLevelRef = useRef(getLevelIndex(state.totalPoints));

  const toggleMission = useCallback(
    (mission: Mission, cardEl: HTMLElement | null) => {
      setState((prev) => {
        const alreadyDone = prev.completedToday.includes(mission.id);
        const today = todayISO();

        if (alreadyDone) {
          // Uncheck: subtract points (floor at 0) and remove from completedToday
          const newPoints = Math.max(0, prev.totalPoints - mission.points);
          const newCompleted = prev.completedToday.filter((id) => id !== mission.id);
          const newMissionsCompleted = Math.max(0, prev.totalMissionsCompleted - 1);

          // Update streak: if today no longer has ≥3 missions, remove today from streak days
          let newStreakDays = prev.streakDays;
          if (newCompleted.length < 3) {
            newStreakDays = prev.streakDays.filter((d) => d !== today);
          }

          return {
            ...prev,
            totalPoints: newPoints,
            totalMissionsCompleted: newMissionsCompleted,
            completedToday: newCompleted,
            streakDays: newStreakDays,
          };
        }

        // Check: add points
        const newPoints = prev.totalPoints + mission.points;
        const newCompleted = [...prev.completedToday, mission.id];
        const newMissionsCompleted = prev.totalMissionsCompleted + 1;

        // Update streak: if today now has ≥3 missions, add today
        let newStreakDays = prev.streakDays;
        if (newCompleted.length >= 3 && !prev.streakDays.includes(today)) {
          newStreakDays = [...prev.streakDays, today];
        }

        // Flash animation
        setFlashingIds((fids) => {
          const next = new Set(fids);
          next.add(mission.id);
          return next;
        });
        setTimeout(() => {
          setFlashingIds((fids) => {
            const next = new Set(fids);
            next.delete(mission.id);
            return next;
          });
        }, 600);

        // Newly-completed shimmer badge (green glow on card)
        setNewlyCompletedIds((ids) => {
          const next = new Set(ids);
          next.add(mission.id);
          return next;
        });
        setTimeout(() => {
          setNewlyCompletedIds((ids) => {
            const next = new Set(ids);
            next.delete(mission.id);
            return next;
          });
        }, 700);

        // XP bar shimmer
        setXpShimmer(true);
        setTimeout(() => setXpShimmer(false), 750);

        // Tactile feedback
        navigator.vibrate?.(50);

        // Floating point
        if (cardEl) {
          const rect = cardEl.getBoundingClientRect();
          const fpId = ++floatingIdRef.current;
          const fp: FloatingPoint = {
            id: fpId,
            value: mission.points,
            x: rect.right - 60,
            y: rect.top + rect.height / 2,
          };
          setFloatingPoints((fps) => [...fps, fp]);
          setTimeout(() => {
            setFloatingPoints((fps) => fps.filter((f) => f.id !== fpId));
          }, 1200);
        }

        // Level up check
        const prevLevel = getLevelIndex(prev.totalPoints);
        const newLevel = getLevelIndex(newPoints);
        if (newLevel > prevLevel) {
          const info = LEVELS[newLevel];
          setLevelUpInfo(info);
          setLevelUpExiting(false);
          setTimeout(() => {
            setLevelUpExiting(true);
            setTimeout(() => setLevelUpInfo(null), 450);
          }, 2000);
        }

        return {
          ...prev,
          totalPoints: newPoints,
          totalMissionsCompleted: newMissionsCompleted,
          completedToday: newCompleted,
          streakDays: newStreakDays,
        };
      });
    },
    [],
  );

  useEffect(() => {
    previousLevelRef.current = getLevelIndex(state.totalPoints);
  }, [state.totalPoints]);

  const resetDay = useCallback(() => {
    setState((prev) => ({
      ...prev,
      completedToday: [],
      lastResetDate: todayISO(),
    }));
    setConfirmReset(false);
  }, []);

  const levelIdx = getLevelIndex(state.totalPoints);
  const levelNum = getLevelNumber(state.totalPoints);
  const levelInfo = LEVELS[levelIdx];
  const xpPct = getXpProgress(state.totalPoints);
  const pointsIntoLevel = state.totalPoints % POINTS_PER_LEVEL;
  const streak = computeStreak(state.streakDays);

  // Sort: incomplete first, then completed
  const sorted = [...MISSIONS].sort((a, b) => {
    const aDone = state.completedToday.includes(a.id) ? 1 : 0;
    const bDone = state.completedToday.includes(b.id) ? 1 : 0;
    return aDone - bDone;
  });

  const isFirstRun = state.totalPoints === 0 && state.completedToday.length === 0;

  return (
    <Wrapper>
      {/* Hero */}
      <HeroCard>
        <LevelBadge>{levelInfo.emoji}</LevelBadge>
        <LevelNumber>{pt ? `Nível ${levelNum}` : `Level ${levelNum}`}</LevelNumber>
        <LevelName>{pt ? levelInfo.pt : levelInfo.en}</LevelName>
        <TotalPoints>
          <span>{state.totalPoints}</span>
          {pt ? 'pontos' : 'points'}
        </TotalPoints>
        <XpBarWrapper>
          <XpBarLabel>
            <span>XP</span>
            <span>{pointsIntoLevel} / {POINTS_PER_LEVEL}</span>
          </XpBarLabel>
          <XpBarTrack>
            <XpBarFill pct={xpPct} shimmer={xpShimmer} />
          </XpBarTrack>
        </XpBarWrapper>
      </HeroCard>

      {/* First-run welcome hero */}
      {isFirstRun && (
        <WelcomeHero>
          <WelcomeRocket>🚀</WelcomeRocket>
          <WelcomeTitle>
            {pt ? 'A tua aventura começa hoje!' : 'Your adventure starts today!'}
          </WelcomeTitle>
          <WelcomeBody>
            {pt
              ? 'Completa missões para ganhar pontos e subir de nível. Quanto mais fizeres, mais forte ficas!'
              : 'Complete missions to earn points and level up. The more you do, the stronger you get!'}
          </WelcomeBody>
        </WelcomeHero>
      )}

      {/* Missions */}
      <div>
        <SectionTitle style={{ marginBottom: theme.spacing.md }}>
          {pt ? '🎯 Missões de Hoje' : '🎯 Today\'s Missions'}
        </SectionTitle>
        <MissionList>
          {sorted.map((mission) => {
            const completed = state.completedToday.includes(mission.id);
            const flashing = flashingIds.has(mission.id);
            const newlyCompleted = newlyCompletedIds.has(mission.id);

            const handleTouchStart = (e: React.TouchEvent) => {
              touchStartRef.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            };

            const handleTouchEnd = (e: React.TouchEvent, el: HTMLElement | null) => {
              if (!touchStartRef.current) return;
              const dx = Math.abs(e.changedTouches[0].clientX - touchStartRef.current.x);
              const dy = Math.abs(e.changedTouches[0].clientY - touchStartRef.current.y);
              touchStartRef.current = null;
              if (dx > 8 || dy > 8) return;
              suppressClickRef.current[mission.id] = true;
              toggleMission(mission, el);
            };

            const handleClick = (e: React.MouseEvent) => {
              if (suppressClickRef.current[mission.id]) {
                suppressClickRef.current[mission.id] = false;
                return;
              }
              toggleMission(mission, e.currentTarget as HTMLElement);
            };

            return (
              <MissionCard
                key={mission.id}
                completed={completed}
                flashing={flashing}
                newlyCompleted={newlyCompleted}
                onClick={handleClick}
                onTouchStart={handleTouchStart}
                onTouchEnd={(e) => handleTouchEnd(e, e.currentTarget as HTMLElement)}
                role="checkbox"
                aria-checked={completed}
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === ' ' || e.key === 'Enter') {
                    e.preventDefault();
                    toggleMission(mission, e.currentTarget as HTMLElement);
                  }
                }}
              >
                <Checkbox checked={completed}>
                  {completed && '✓'}
                </Checkbox>
                <MissionInfo>
                  <MissionEmoji>{mission.emoji}</MissionEmoji>
                  <MissionName completed={completed}>
                    {pt ? mission.name.pt : mission.name.en}
                  </MissionName>
                </MissionInfo>
                <PointsBadge completed={completed}>
                  +{mission.points} pts
                </PointsBadge>
                {completed && <CompletedBadge>✓</CompletedBadge>}
              </MissionCard>
            );
          })}
        </MissionList>
      </div>

      {/* Stats */}
      <div>
        <SectionTitle style={{ marginBottom: theme.spacing.md }}>
          {pt ? '📊 As Tuas Estatísticas' : '📊 Your Stats'}
        </SectionTitle>
        <StatsGrid>
          <StatCard>
            <StatEmoji>✅</StatEmoji>
            <StatValue>{state.totalMissionsCompleted}</StatValue>
            <StatLabel>{pt ? 'Missões\nconcluídas' : 'Missions\ncompleted'}</StatLabel>
          </StatCard>
          <StatCard>
            <StatEmoji>⭐</StatEmoji>
            <StatValue>{state.totalPoints}</StatValue>
            <StatLabel>{pt ? 'Pontos\nganhos' : 'Points\nearned'}</StatLabel>
          </StatCard>
          <StreakCard>
            <StreakEmoji>🔥</StreakEmoji>
            <StreakValue>{streak}</StreakValue>
            <StreakLabel>{pt ? 'Dias\nseguidos' : 'Day\nstreak'}</StreakLabel>
          </StreakCard>
        </StatsGrid>
      </div>

      {/* Actions */}
      <ActionsRow>
        {confirmReset ? (
          <ConfirmRow>
            <ConfirmText>
              {pt
                ? 'Tens a certeza? As missões de hoje serão limpas, mas os teus pontos ficam.'
                : 'Are you sure? This clears today\'s missions but keeps your points.'}
            </ConfirmText>
            <ConfirmButtons>
              <ConfirmYes onClick={resetDay}>
                {pt ? 'Confirmar' : 'Confirm'}
              </ConfirmYes>
              <ConfirmNo onClick={() => setConfirmReset(false)}>
                {pt ? 'Cancelar' : 'Cancel'}
              </ConfirmNo>
            </ConfirmButtons>
          </ConfirmRow>
        ) : (
          <ResetButton onClick={() => setConfirmReset(true)}>
            🔄 {pt ? 'Novo dia' : 'Reset day'}
          </ResetButton>
        )}
      </ActionsRow>

      {/* Floating points */}
      {floatingPoints.map((fp) => (
        <FloatingPointEl
          key={fp.id}
          style={{ left: fp.x, top: fp.y }}
        >
          +{fp.value}
        </FloatingPointEl>
      ))}

      {/* Level up overlay */}
      {levelUpInfo && (
        <LevelUpOverlay exiting={levelUpExiting}>
          <LevelUpCard>
            <LevelUpEmoji>{levelUpInfo.emoji}</LevelUpEmoji>
            <LevelUpTitle>
              {pt ? '🎉 Subiste de nível!' : '🎉 Level Up!'}
            </LevelUpTitle>
            <LevelUpName>
              {pt ? levelUpInfo.pt : levelUpInfo.en}
            </LevelUpName>
          </LevelUpCard>
        </LevelUpOverlay>
      )}
    </Wrapper>
  );
}
