// ─── Types ────────────────────────────────────────────────────────────────────

interface Scene {
  id: string;
  emoji: string;
  text: { pt: string; en: string };
  choices?: { label: { pt: string; en: string }; next: string }[];
  isEnding?: boolean;
  endingType?: 'good' | 'neutral';
}

interface Story {
  id: string;
  emoji: string;
  title: { pt: string; en: string };
  description: { pt: string; en: string };
  color: string;
  totalEndings: number;
  scenes: Scene[];
}

interface Progress {
  [storyId: string]: string[]; // list of ending scene IDs discovered
}

interface TextAdventureProps {
  lang: string;
  onBack: () => void;
}

// ─── Local Storage ────────────────────────────────────────────────────────────

const STORAGE_KEY = 'atlantis-textadventure-progress';

function loadProgress(): Progress {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Progress) : {};
  } catch {
    return {};
  }
}

function saveProgress(progress: Progress): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(progress));
  } catch {
    // ignore
  }
}

