const CONFETTI_COLORS = ['#f0883e', '#58a6ff', '#3fb950', '#e3b341', '#bc8cff', '#f78166'];

interface ConfettiProps {
  count?: number;
}

function Confetti({ count = 60 }: ConfettiProps) {
  const pieces = useMemo(
    () =>
      Array.from({ length: count }, (_, i) => ({
        id: i,
        left: Math.random() * 100,
        delay: Math.random() * 2,
        duration: 2.5 + Math.random() * 2,
        color: CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)] ?? '#58a6ff',
        size: 6 + Math.floor(Math.random() * 8),
      })),
    [count],
  );

  return (
    <>
      {pieces.map((p) => (
        <ConfettiPiece
          key={p.id}
          left={p.left}
          delay={p.delay}
          duration={p.duration}
          color={p.color}
          size={p.size}
        />
      ))}
    </>
  );
}

// ─── High score helpers ───────────────────────────────────────────────────────

const STORAGE_KEY = 'atlantis-familyquiz-scores';

function loadHighScores(): Record<string, number> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Record<string, number>) : {};
  } catch {
    return {};
  }
}

function saveHighScore(categoryId: string, score: number): void {
  const scores = loadHighScores();
  if ((scores[categoryId] ?? 0) < score) {
    scores[categoryId] = score;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(scores));
    } catch {
      // ignore storage errors
    }
  }
}

