// ─── Main component ───────────────────────────────────────────────────────────

const QUESTION_TIME = 15; // seconds per question
const BONUS_THRESHOLD = 5; // seconds remaining for bonus
const BONUS_POINTS = 5;

export function FamilyQuiz({ lang, onBack }: FamilyQuizProps) {
  const [phase, setPhase] = useState<GamePhase>('categories');
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [answerState, setAnswerState] = useState<AnswerState>('idle');
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [highScores, setHighScores] = useState<Record<string, number>>(loadHighScores);
  const [timeLeft, setTimeLeft] = useState(QUESTION_TIME);
  const [timerKey, setTimerKey] = useState(0); // forces bar re-mount on new question
  const [gotBonus, setGotBonus] = useState(false);
  const questionStartTime = useRef<number>(Date.now());
  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const advanceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const touchStart = useRef<{ x: number; y: number } | null>(null);
  const suppressClick = useRef(false);

  const stopCountdown = useCallback(() => {
    if (countdownRef.current) {
      clearInterval(countdownRef.current);
      countdownRef.current = null;
    }
  }, []);

  const cleanup = useCallback(() => {
    if (advanceTimer.current) {
      clearTimeout(advanceTimer.current);
      advanceTimer.current = null;
    }
    stopCountdown();
  }, [stopCountdown]);

  useEffect(() => () => cleanup(), [cleanup]);

  const startQuestion = useCallback(() => {
    stopCountdown();
    setTimeLeft(QUESTION_TIME);
    setTimerKey((k) => k + 1);
    questionStartTime.current = Date.now();
    countdownRef.current = setInterval(() => {
      setTimeLeft((t) => {
        if (t <= 1) {
          // Time's up — handled by the effect below via timeLeft reaching 0
          return 0;
        }
        return t - 1;
      });
    }, 1000);
  }, [stopCountdown]);

  const startCategory = useCallback((cat: Category) => {
    cleanup();
    setSelectedCategory(cat);
    setQuestionIndex(0);
    setScore(0);
    setAnswerState('idle');
    setSelectedOption(null);
    setPhase('playing');
  }, [cleanup]);

  // Start countdown when entering playing phase or moving to next question
  useEffect(() => {
    if (phase === 'playing' && answerState === 'idle') {
      startQuestion();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, questionIndex]);

  // Timeout: time ran out — count as wrong
  useEffect(() => {
    if (timeLeft === 0 && phase === 'playing' && answerState === 'idle' && selectedCategory) {
      stopCountdown();
      setAnswerState('wrong');
      setSelectedOption(null);
      setGotBonus(false);

      const nextScore = score; // no points for timeout
      advanceTimer.current = setTimeout(() => {
        const nextIndex = questionIndex + 1;
        if (nextIndex >= selectedCategory.questions.length) {
          saveHighScore(selectedCategory.id, nextScore);
          setHighScores(loadHighScores());
          setScore(nextScore);
          setPhase('results');
        } else {
          setScore(nextScore);
          setQuestionIndex(nextIndex);
          setAnswerState('idle');
          setSelectedOption(null);
        }
      }, 1500);
    }
  }, [timeLeft, phase, answerState, selectedCategory, questionIndex, score, stopCountdown]);

  const handleAnswer = useCallback(
    (optionIdx: number) => {
      if (answerState !== 'idle' || !selectedCategory) return;
      const question = selectedCategory.questions[questionIndex];
      if (!question) return;

      stopCountdown();
      const elapsed = (Date.now() - questionStartTime.current) / 1000;
      const isCorrect = optionIdx === question.correct;
      const hasBonus = isCorrect && elapsed < BONUS_THRESHOLD;
      const bonus = hasBonus ? BONUS_POINTS : 0;

      setGotBonus(hasBonus);
      setSelectedOption(optionIdx);
      setAnswerState(isCorrect ? 'correct' : 'wrong');

      const nextScore = score + (isCorrect ? 10 : 0) + bonus;

      advanceTimer.current = setTimeout(() => {
        const nextIndex = questionIndex + 1;
        if (nextIndex >= selectedCategory.questions.length) {
          saveHighScore(selectedCategory.id, nextScore);
          setHighScores(loadHighScores());
          setScore(nextScore);
          setPhase('results');
        } else {
          setScore(nextScore);
          setQuestionIndex(nextIndex);
          setAnswerState('idle');
          setSelectedOption(null);
          setGotBonus(false);
        }
      }, 1500);
    },
    [answerState, selectedCategory, questionIndex, score, stopCountdown],
  );

  const makeOptionTouchHandlers = (optionIdx: number) => ({
    onTouchStart: (e: React.TouchEvent) => {
      touchStart.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    },
    onTouchEnd: (e: React.TouchEvent) => {
      if (!touchStart.current) return;
      const dx = Math.abs(e.changedTouches[0].clientX - touchStart.current.x);
      const dy = Math.abs(e.changedTouches[0].clientY - touchStart.current.y);
      touchStart.current = null;
      if (dx > 8 || dy > 8) return;
      suppressClick.current = true;
      handleAnswer(optionIdx);
    },
    onClick: () => {
      if (suppressClick.current) {
        suppressClick.current = false;
        return;
      }
      handleAnswer(optionIdx);
    },
  });

  // ── Category screen ────────────────────────────────────────────────────────
  if (phase === 'categories') {
    return (
      <Wrapper>
        <TopBar>
          <Title>
            🧠 {tx('title', lang)}
          </Title>
        </TopBar>
        <p
          style={{
            color: theme.colors.mainTextMuted,
            marginBottom: theme.spacing.lg,
            fontSize: theme.typography.fontSizeMd,
          }}
        >
          {tx('chooseCategory', lang)}
        </p>
        <CategoryGrid>
          {CATEGORIES.map((cat) => {
            const best = highScores[cat.id];
            return (
              <CategoryCard
                key={cat.id}
                catColor={cat.color}
                onClick={() => startCategory(cat)}
              >
                <CategoryIcon>{cat.icon}</CategoryIcon>
                <CategoryLabel>{lang === 'pt' ? cat.label.pt : cat.label.en}</CategoryLabel>
                {best !== undefined && (
                  <HighScore catColor={cat.color}>
                    {tx('highScore', lang)} {best}/{cat.questions.length * 10}
                  </HighScore>
                )}
              </CategoryCard>
            );
          })}
        </CategoryGrid>
      </Wrapper>
    );
  }

  // ── Playing screen ─────────────────────────────────────────────────────────
  if (phase === 'playing' && selectedCategory) {
    const question = selectedCategory.questions[questionIndex];
    if (!question) return null;

    const total = selectedCategory.questions.length;
    const pct = ((questionIndex + 1) / total) * 100;

    return (
      <Wrapper>
        <TopBar>
          <BackBtn onClick={() => { cleanup(); setPhase('categories'); }}>
            {tx('back', lang)}
          </BackBtn>
          <Title>
            {selectedCategory.icon} {lang === 'pt' ? selectedCategory.label.pt : selectedCategory.label.en}
          </Title>
        </TopBar>

        <PlayWrapper>
          <ScoreBar>
            <ScorePill catColor={selectedCategory.color}>
              {tx('score', lang)}: {score}
            </ScorePill>
            <ProgressOuter>
              <ProgressInner pct={pct} catColor={selectedCategory.color} />
            </ProgressOuter>
            <ProgressLabel>
              {tx('question', lang)} {questionIndex + 1} {tx('of', lang)} {total}
            </ProgressLabel>
            <TimerLabel urgent={timeLeft <= 5}>{timeLeft}s</TimerLabel>
          </ScoreBar>

          <QuestionCard key={questionIndex} catColor={selectedCategory.color}>
            <TimerBar
              key={timerKey}
              duration={QUESTION_TIME}
              catColor={selectedCategory.color}
              urgent={timeLeft <= 5}
            />
            <QuestionText>
              {lang === 'pt' ? question.q.pt : question.q.en}
            </QuestionText>
            <OptionsGrid>
              {question.options.map((opt, i) => {
                let status: OptionStatus = 'idle';
                if (answerState !== 'idle') {
                  if (i === question.correct) {
                    status = selectedOption === i ? 'correct' : 'highlight';
                  } else if (i === selectedOption) {
                    status = 'wrong';
                  }
                }

                return (
                  <OptionBtn
                    key={i}
                    status={status}
                    catColor={selectedCategory.color}
                    disabled={answerState !== 'idle'}
                    {...makeOptionTouchHandlers(i)}
                  >
                    <OptionLetter status={status} catColor={selectedCategory.color}>
                      {LETTERS[i]}
                    </OptionLetter>
                    {lang === 'pt' ? opt.pt : opt.en}
                  </OptionBtn>
                );
              })}
            </OptionsGrid>
          </QuestionCard>

          {answerState !== 'idle' && (
            <FeedbackBanner isCorrect={answerState === 'correct'}>
              {answerState === 'correct'
                ? gotBonus
                  ? tx('correctBonus', lang)
                  : tx('correct', lang)
                : selectedOption === null
                ? tx('timeUp', lang)
                : tx('wrong', lang)}
            </FeedbackBanner>
          )}
        </PlayWrapper>
      </Wrapper>
    );
  }

  // ── Results screen ─────────────────────────────────────────────────────────
  if (phase === 'results' && selectedCategory) {
    const total = selectedCategory.questions.length;
    const maxScore = total * 10;
    const pct = Math.round((score / maxScore) * 100);
    const stars = pct === 100 ? 3 : pct >= 60 ? 2 : 1;

    const messages: Record<number, string> = {
      3: tx('msg3stars', lang),
      2: tx('msg2stars', lang),
      1: tx('msg1star', lang),
    };

    return (
      <Wrapper>
        {stars === 3 && <Confetti />}
        <TopBar>
          <BackBtn onClick={() => setPhase('categories')}>{tx('back', lang)}</BackBtn>
          <Title>
            {selectedCategory.icon} {tx('results', lang)}
          </Title>
        </TopBar>

        <ResultsWrapper>
          <ResultsCard catColor={selectedCategory.color}>
            <ResultsTitle>{tx('results', lang)}</ResultsTitle>
            <ResultsScore catColor={selectedCategory.color}>{score}</ResultsScore>
            <ResultsPct>
              {pct}% — {score}/{maxScore}
            </ResultsPct>

            <StarsRow>
              {[1, 2, 3].map((s) => (
                <Star key={s} lit={s <= stars} delay={(s - 1) * 0.15}>
                  ⭐
                </Star>
              ))}
            </StarsRow>

            <ResultsMessage>{messages[stars]}</ResultsMessage>
          </ResultsCard>

          <ResultsBtns>
            <ActionBtn
              primary
              catColor={selectedCategory.color}
              onClick={() => startCategory(selectedCategory)}
            >
              {tx('retry', lang)}
            </ActionBtn>
            <ActionBtn onClick={() => setPhase('categories')}>
              {tx('categories', lang)}
            </ActionBtn>
          </ResultsBtns>
        </ResultsWrapper>
      </Wrapper>
    );
  }

  return null;
}
