// ─── Helpers ──────────────────────────────────────────────────────────────────

const PAIRS: Record<Difficulty, number> = { easy: 8, medium: 12, hard: 20 };

function shuffleArray<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function buildDeck(symbols: string[], numPairs: number): MemoryCard[] {
  const picked = shuffleArray(symbols).slice(0, numPairs);
  const cards: MemoryCard[] = [];
  picked.forEach((sym, i) => {
    cards.push({ id: i * 2, symbol: sym, pairId: i, flipped: false, matched: false });
    cards.push({ id: i * 2 + 1, symbol: sym, pairId: i, flipped: false, matched: false });
  });
  return shuffleArray(cards);
}

function formatTime(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
}

