const CONFETTI_EMOJIS = ['🎊', '⭐', '🌟', '💫', '✨', '🎉', '🏆', '🥳'];
const CONFETTI_COLORS = ['#f97583', '#d2a8ff', '#79c0ff', '#3fb950', '#f59e0b', '#ff6bcb'];
const CHEERS: (keyof typeof T)[] = ['great', 'amazing', 'perfect', 'super', 'wow', 'fast'];

const STORAGE_KEY = 'atlantis-memory-best';

function getBest(difficulty: Difficulty): number {
  try {
    const data = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '{}');
    return data[difficulty] ?? 0;
  } catch { return 0; }
}

function saveBest(difficulty: Difficulty, moves: number): void {
  try {
    const data = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '{}');
    // Lower is better for moves — only save if lower or first time
    if (!data[difficulty] || moves < data[difficulty]) {
      data[difficulty] = moves;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    }
  } catch { /* noop */ }
}

function getGridCols(difficulty: Difficulty): number {
  if (difficulty === 'easy') return 4;   // 16 cards → 4×4
  if (difficulty === 'medium') return 6; // 24 cards → 4×6
  return 8;                               // 40 cards → 5×8
}

function getSymbolSize(difficulty: Difficulty): 'sm' | 'md' | 'lg' {
  if (difficulty === 'easy') return 'lg';
  if (difficulty === 'medium') return 'md';
  return 'sm';
}

export function MemoryGame({ lang }: MemoryGameProps) {
  const [phase, setPhase] = useState<Phase>('theme');
  const [symbolTheme, setSymbolTheme] = useState<SymbolTheme>('animals');
  const [difficulty, setDifficulty] = useState<Difficulty>('easy');
  const [cards, setCards] = useState<MemoryCard[]>([]);
  const [flippedIds, setFlippedIds] = useState<number[]>([]);
  const [wrongIds, setWrongIds] = useState<Set<number>>(new Set());
  const [moves, setMoves] = useState(0);
  const [matchedPairs, setMatchedPairs] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [feedback, setFeedback] = useState<{ msg: string; type: 'match' | 'miss' | 'info' }>({ msg: '', type: 'info' });
  const [isNewRecord, setIsNewRecord] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);

  const lockRef = useRef(false);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const totalPairs = PAIRS[difficulty];
  const gridCols = getGridCols(difficulty);
  const symSize = getSymbolSize(difficulty);

  const themeSymbols = useMemo(() => {
    const th = THEMES.find((tt) => tt.id === symbolTheme);
    return th?.symbols ?? THEMES[0].symbols;
  }, [symbolTheme]);

  // Timer
  useEffect(() => {
    if (phase !== 'playing') {
      if (timerRef.current) clearInterval(timerRef.current);
      return;
    }
    timerRef.current = setInterval(() => setElapsed((p) => p + 1), 1000);
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [phase]);

  const startGame = useCallback((diff: Difficulty) => {
    setDifficulty(diff);
    const deck = buildDeck(themeSymbols, PAIRS[diff]);
    setCards(deck);
    setFlippedIds([]);
    setWrongIds(new Set());
    setMoves(0);
    setMatchedPairs(0);
    setElapsed(0);
    setFeedback({ msg: t('flipTwo', lang), type: 'info' });
    setIsNewRecord(false);
    setShowConfetti(false);
    setPhase('playing');
  }, [themeSymbols, lang]);

  const handleCardClick = useCallback((card: MemoryCard) => {
    if (lockRef.current || card.matched || card.flipped) return;

    const newFlipped = [...flippedIds, card.id];
    setFlippedIds(newFlipped);
    setCards((prev) => prev.map((c) => c.id === card.id ? { ...c, flipped: true } : c));

    if (newFlipped.length === 2) {
      lockRef.current = true;
      setMoves((p) => p + 1);

      const [firstId, secondId] = newFlipped;
      const first = cards.find((c) => c.id === firstId)!;
      const second = card;

      if (first.pairId === second.pairId) {
        // Match!
        const newMatched = matchedPairs + 1;
        setMatchedPairs(newMatched);
        const cheer = CHEERS[Math.floor(Math.random() * CHEERS.length)];
        setFeedback({ msg: `${t(cheer, lang)} ${t('matched', lang)}`, type: 'match' });

        setTimeout(() => {
          setCards((prev) => prev.map((c) =>
            c.pairId === first.pairId ? { ...c, matched: true } : c
          ));
          setFlippedIds([]);
          lockRef.current = false;

          // Check win
          if (newMatched === totalPairs) {
            setFeedback({ msg: t('allFound', lang), type: 'match' });
            const currentMoves = moves + 1;
            const best = getBest(difficulty);
            if (!best || currentMoves < best) {
              saveBest(difficulty, currentMoves);
              setIsNewRecord(true);
            }
            setShowConfetti(true);
            setTimeout(() => setPhase('gameover'), 1200);
          }
        }, 500);
      } else {
        // No match
        setFeedback({ msg: t('tryAgain', lang), type: 'miss' });
        setWrongIds(new Set([firstId, secondId]));

        setTimeout(() => {
          setCards((prev) => prev.map((c) =>
            c.id === firstId || c.id === secondId ? { ...c, flipped: false } : c
          ));
          setFlippedIds([]);
          setWrongIds(new Set());
          lockRef.current = false;
        }, 800);
      }
    }
  }, [flippedIds, cards, matchedPairs, totalPairs, moves, difficulty, lang]);

  const best = getBest(difficulty);

  // ─── Theme Picker ───────────────────────────────────────────────────────────

  if (phase === 'theme') {
    return (
      <Wrapper>
        <MenuWrap>
          <MenuTitle>🃏 {t('title', lang)}</MenuTitle>
          <MenuSubtitle>{t('pickTheme', lang)}</MenuSubtitle>
          <ThemeGrid>
            {THEMES.map((th) => (
              <ThemeCard
                key={th.id}
                accent={th.color}
                onClick={() => { setSymbolTheme(th.id); setPhase('difficulty'); }}
              >
                <ThemeEmoji>{th.emoji}</ThemeEmoji>
                <ThemeLabel>{t(th.id as keyof typeof T, lang)}</ThemeLabel>
                <ThemePreview>{th.preview.map((e, i) => <span key={i}>{e}</span>)}</ThemePreview>
                <ThemeDesc>{t(`${th.id}Desc` as keyof typeof T, lang)}</ThemeDesc>
              </ThemeCard>
            ))}
          </ThemeGrid>
        </MenuWrap>
      </Wrapper>
    );
  }

  // ─── Difficulty Picker ──────────────────────────────────────────────────────

  if (phase === 'difficulty') {
    return (
      <Wrapper>
        <MenuWrap>
          <MenuTitle>🃏 {t('title', lang)}</MenuTitle>
          <MenuSubtitle>{t('pickSize', lang)}</MenuSubtitle>
          <DiffCards>
            <DiffCard accent="#3fb950" onClick={() => startGame('easy')}>
              <DiffEmoji>🌟</DiffEmoji>
              <DiffLabel>{t('easy', lang)}</DiffLabel>
              <DiffDesc>{t('easyDesc', lang)}</DiffDesc>
            </DiffCard>
            <DiffCard accent="#f59e0b" onClick={() => startGame('medium')}>
              <DiffEmoji>🔥</DiffEmoji>
              <DiffLabel>{t('medium', lang)}</DiffLabel>
              <DiffDesc>{t('mediumDesc', lang)}</DiffDesc>
            </DiffCard>
            <DiffCard accent="#f97583" onClick={() => startGame('hard')}>
              <DiffEmoji>💪</DiffEmoji>
              <DiffLabel>{t('hard', lang)}</DiffLabel>
              <DiffDesc>{t('hardDesc', lang)}</DiffDesc>
            </DiffCard>
          </DiffCards>
          {best > 0 && (
            <BestBadge>🏆 {t('bestMoves', lang)}: {best} {t('finalMoves', lang)}</BestBadge>
          )}
        </MenuWrap>
      </Wrapper>
    );
  }

  // ─── Game Over ──────────────────────────────────────────────────────────────

  if (phase === 'gameover') {
    return (
      <Wrapper>
        {showConfetti && CONFETTI_EMOJIS.map((e, i) => (
          <Confetti key={i} left={5 + i * 12} delay={i * 0.1} color={CONFETTI_COLORS[i % CONFETTI_COLORS.length]}>{e}</Confetti>
        ))}
        <GameOverWrap>
          <GameOverEmoji>🏆</GameOverEmoji>
          <GameOverTitle>{t('gameOver', lang)}</GameOverTitle>
          <ShimmerText>{t('allFound', lang)}</ShimmerText>
          <StatRow>
            <StatBlock>
              <StatLabel>{t('moves', lang)}</StatLabel>
              <StatValue>{moves}</StatValue>
            </StatBlock>
            <StatBlock>
              <StatLabel>{t('pairs', lang)}</StatLabel>
              <StatValue color="#3fb950">{totalPairs}</StatValue>
            </StatBlock>
            <StatBlock>
              <StatLabel>{t('finalTime', lang)}</StatLabel>
              <StatValue color="#f59e0b">{formatTime(elapsed)}</StatValue>
            </StatBlock>
          </StatRow>
          {isNewRecord && <NewRecord>🎉 {t('newRecord', lang)}</NewRecord>}
          {best > 0 && !isNewRecord && (
            <BestBadge>🏆 {t('bestMoves', lang)}: {best} {t('finalMoves', lang)}</BestBadge>
          )}
          <PlayBtn accent="#8b5cf6" onClick={() => setPhase('theme')}>
            {t('playAgain', lang)}
          </PlayBtn>
        </GameOverWrap>
      </Wrapper>
    );
  }

  // ─── Playing ────────────────────────────────────────────────────────────────

  return (
    <Wrapper>
      <GameWrap>
        <TopRow>
          <StatBadge>🎴 {t('moves', lang)}: {moves}</StatBadge>
          <StatBadge highlight={matchedPairs === totalPairs}>
            ⭐ {t('pairs', lang)}: {matchedPairs}/{totalPairs}
          </StatBadge>
          <StatBadge>⏱️ {formatTime(elapsed)}</StatBadge>
        </TopRow>

        <FeedbackMsg key={feedback.msg} type={feedback.type}>
          {feedback.msg}
        </FeedbackMsg>

        <Board cols={gridCols}>
          {cards.map((card) => (
            <CardOuter
              key={card.id}
              className="card-outer"
              matched={card.matched}
              wrong={wrongIds.has(card.id)}
              onClick={() => handleCardClick(card)}
              aria-label={card.flipped ? card.symbol : 'Hidden card'}
            >
              <CardInner flipped={card.flipped}>
                <CardBack />
                <CardFront matched={card.matched}>
                  <CardSymbol size={symSize}>{card.symbol}</CardSymbol>
                  {card.matched && (
                    <>
                      <MatchStar i={0}>✨</MatchStar>
                      <MatchStar i={1}>✨</MatchStar>
                    </>
                  )}
                </CardFront>
              </CardInner>
            </CardOuter>
          ))}
        </Board>
      </GameWrap>
    </Wrapper>
  );
}
