type CellValue = 'X' | 'O' | null;
type Board = CellValue[];
type Difficulty = 'easy' | 'medium' | 'hard';
type GameMode = 'bot' | '2p';

interface TicTacToeProps {
  lang: string;
  onBack: () => void;
}

const WINNING_LINES = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8],
  [0, 3, 6], [1, 4, 7], [2, 5, 8],
  [0, 4, 8], [2, 4, 6],
];

function checkWinner(board: Board): { winner: CellValue; line: number[] | null } {
  for (const combo of WINNING_LINES) {
    const [a, b, c] = combo;
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return { winner: board[a], line: combo };
    }
  }
  return { winner: null, line: null };
}

function getEmptyCells(board: Board): number[] {
  return board.reduce<number[]>((acc, v, i) => (v === null ? [...acc, i] : acc), []);
}

function minimax(board: Board, isMax: boolean): number {
  const { winner } = checkWinner(board);
  if (winner === 'O') return 10;
  if (winner === 'X') return -10;
  const empty = getEmptyCells(board);
  if (empty.length === 0) return 0;

  if (isMax) {
    let best = -Infinity;
    for (const i of empty) {
      board[i] = 'O';
      best = Math.max(best, minimax(board, false));
      board[i] = null;
    }
    return best;
  } else {
    let best = Infinity;
    for (const i of empty) {
      board[i] = 'X';
      best = Math.min(best, minimax(board, true));
      board[i] = null;
    }
    return best;
  }
}

function getBotMove(board: Board, difficulty: Difficulty): number {
  const empty = getEmptyCells(board);
  if (empty.length === 0) return -1;

  if (difficulty === 'easy') {
    // 70% random, 30% smart
    if (Math.random() < 0.7) return empty[Math.floor(Math.random() * empty.length)];
  } else if (difficulty === 'medium') {
    // 30% random, 70% smart
    if (Math.random() < 0.3) return empty[Math.floor(Math.random() * empty.length)];
  }

  // Smart move (minimax)
  let bestScore = -Infinity;
  let bestMove = empty[0];
  for (const i of empty) {
    board[i] = 'O';
    const score = minimax(board, false);
    board[i] = null;
    if (score > bestScore) {
      bestScore = score;
      bestMove = i;
    }
  }
  return bestMove;
}

