const PLAYER_EMOJI = '⭐';
const BOT_EMOJI = '🤖';
const PLAYER2_EMOJI = '🌙';

const SCORE_KEY = 'atlantis-tictactoe-score';

interface Score {
  wins: number;
  losses: number;
  draws: number;
}

function loadScore(): Score {
  try {
    const raw = localStorage.getItem(SCORE_KEY);
    if (raw) return JSON.parse(raw) as Score;
  } catch { /* ignore */ }
  return { wins: 0, losses: 0, draws: 0 };
}

function saveScore(score: Score) {
  localStorage.setItem(SCORE_KEY, JSON.stringify(score));
}

