const CONFETTI_COLORS = ['#f97583', '#58a6ff', '#3fb950', '#d2a922', '#d2a8ff', '#79c0ff'];

// ─── Component ───────────────────────────────────────────────────────────────

export function TicTacToe({ lang, onBack }: TicTacToeProps) {
  const [board, setBoard] = useState<Board>(Array(9).fill(null));
  const [lastPlaced, setLastPlaced] = useState<number | null>(null);
  const [isPlayerTurn, setIsPlayerTurn] = useState(true);
  const [difficulty, setDifficulty] = useState<Difficulty>('medium');
  const [mode, setMode] = useState<GameMode>('bot');
  const [score, setScore] = useState<Score>(loadScore);
  const [gameOver, setGameOver] = useState(false);
  const [poppedScore, setPoppedScore] = useState<keyof Score | null>(null);
  const boardRef = useRef<Board>(board);
  boardRef.current = board;

  const { winner, line } = checkWinner(board);
  const isDraw = !winner && getEmptyCells(board).length === 0;

  const resetGame = useCallback(() => {
    setBoard(Array(9).fill(null));
    setLastPlaced(null);
    setIsPlayerTurn(true);
    setGameOver(false);
  }, []);

  // Handle game end
  useEffect(() => {
    if (gameOver) return;
    if (winner || isDraw) {
      setGameOver(true);
      if (mode === 'bot') {
        const popped: keyof Score = winner === 'X' ? 'wins' : winner === 'O' ? 'losses' : 'draws';
        setPoppedScore(popped);
        setTimeout(() => setPoppedScore(null), 500);
        setScore((prev) => {
          const next = { ...prev };
          if (winner === 'X') next.wins++;
          else if (winner === 'O') next.losses++;
          else next.draws++;
          saveScore(next);
          return next;
        });
      }
    }
  }, [winner, isDraw, gameOver, mode]);

  // Bot move
  useEffect(() => {
    if (mode === '2p' || isPlayerTurn || gameOver || winner || isDraw) return;
    const timer = setTimeout(() => {
      const current = boardRef.current;
      const move = getBotMove([...current], difficulty);
      if (move >= 0) {
        const next = [...current];
        next[move] = 'O';
        setBoard(next);
        setLastPlaced(move);
        setIsPlayerTurn(true);
      }
    }, 500);
    return () => clearTimeout(timer);
  }, [isPlayerTurn, gameOver, winner, isDraw, difficulty, mode]);

  const handleCellClick = (index: number) => {
    if (board[index] || gameOver) return;
    if (mode === 'bot' && !isPlayerTurn) return;

    const next = [...board];
    const mark: CellValue = isPlayerTurn ? 'X' : 'O';
    next[index] = mark;
    setBoard(next);
    setLastPlaced(index);
    setIsPlayerTurn(!isPlayerTurn);
  };

  const changeDifficulty = (d: Difficulty) => {
    setDifficulty(d);
    resetGame();
  };

  const changeMode = (m: GameMode) => {
    setMode(m);
    resetGame();
  };

  const t = (key: string) => LABELS[key]?.[lang] ?? LABELS[key]?.en ?? key;

  // Status logic depends on mode
  let statusVariant: 'turn' | 'win' | 'lose' | 'draw';
  let statusText: string;

  if (mode === '2p') {
    if (winner === 'X') { statusVariant = 'win'; statusText = t('player1Wins'); }
    else if (winner === 'O') { statusVariant = 'win'; statusText = t('player2Wins'); }
    else if (isDraw) { statusVariant = 'draw'; statusText = t('draw'); }
    else { statusVariant = 'turn'; statusText = isPlayerTurn ? t('player1Turn') : t('player2Turn'); }
  } else {
    if (winner === 'X') { statusVariant = 'win'; statusText = t('youWin'); }
    else if (winner === 'O') { statusVariant = 'lose'; statusText = t('youLose'); }
    else if (isDraw) { statusVariant = 'draw'; statusText = t('draw'); }
    else { statusVariant = 'turn'; statusText = isPlayerTurn ? t('yourTurn') : t('thinking'); }
  }

  const winningSet = new Set(line ?? []);
  const showConfetti = mode === 'bot' ? winner === 'X' : !!winner;
  const isBotThinking = mode === 'bot' && !isPlayerTurn && !gameOver;

  // Pre-generate stable confetti positions to avoid re-render jumps
  const confettiPieces = useMemo(
    () =>
      showConfetti
        ? Array.from({ length: 12 }, (_, i) => ({
            left: 10 + Math.random() * 80,
            delay: Math.random() * 0.5,
            color: CONFETTI_COLORS[i % CONFETTI_COLORS.length],
          }))
        : [],
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [showConfetti],
  );

  // Calculate strike line geometry from winning cell positions
  const strikeStyle = useMemo((): React.CSSProperties | null => {
    if (!line) return null;
    const cellSizePx = Math.min(120, Math.max(80, window.innerWidth * 0.2));
    const gap = 8;
    const pad = 8;

    const cellCenter = (idx: number) => {
      const col = idx % 3;
      const row = Math.floor(idx / 3);
      return {
        x: pad + col * (cellSizePx + gap) + cellSizePx / 2,
        y: pad + row * (cellSizePx + gap) + cellSizePx / 2,
      };
    };

    const from = cellCenter(line[0]);
    const to = cellCenter(line[2]);
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const length = Math.sqrt(dx * dx + dy * dy);
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);

    return {
      left: `${from.x}px`,
      top: `${from.y - 3}px`,
      width: `${length}px`,
      transform: `rotate(${angle}deg)`,
    };
  }, [line]);

  const strikeColor = mode === 'bot'
    ? winner === 'X' ? '#3fb950' : '#f97583'
    : winner === 'X' ? '#58a6ff' : '#d2a8ff';

  const cellEmoji = (cell: CellValue) => {
    if (!cell) return null;
    if (cell === 'X') return PLAYER_EMOJI;
    return mode === '2p' ? PLAYER2_EMOJI : BOT_EMOJI;
  };

  return (
    <Wrapper>
      <Header>
        <Title>❌ ⭕ {t('title')}</Title>
        <ModeBar>
          <ModeBtn active={mode === 'bot'} color={theme.colors.accent} onClick={() => changeMode('bot')}>🤖 {t('vsRobot')}</ModeBtn>
          <ModeBtn active={mode === '2p'} color="#d2a8ff" onClick={() => changeMode('2p')}>👫 {t('vsFriend')}</ModeBtn>
        </ModeBar>
        {mode === 'bot' && (
          <DifficultyBar>
            <DiffBtn active={difficulty === 'easy'} color="#3fb950" onClick={() => changeDifficulty('easy')}>{t('easy')}</DiffBtn>
            <DiffBtn active={difficulty === 'medium'} color="#d2a922" onClick={() => changeDifficulty('medium')}>{t('medium')}</DiffBtn>
            <DiffBtn active={difficulty === 'hard'} color="#f97583" onClick={() => changeDifficulty('hard')}>{t('hard')}</DiffBtn>
          </DifficultyBar>
        )}
      </Header>

      <Legend>
        <LegendItem>{PLAYER_EMOJI} = {mode === '2p' ? t('player1') : t('you')}</LegendItem>
        <LegendItem>{mode === '2p' ? PLAYER2_EMOJI : BOT_EMOJI} = {mode === '2p' ? t('player2') : t('robot')}</LegendItem>
      </Legend>

      <StatusBadge variant={statusVariant}>
        {statusText}
        {isBotThinking && (
          <ThinkingDots>
            <ThinkingDot delay={0} />
            <ThinkingDot delay={0.2} />
            <ThinkingDot delay={0.4} />
          </ThinkingDots>
        )}
      </StatusBadge>

      <BoardContainer>
        {confettiPieces.map((p, i) => (
          <Confetti key={i} left={p.left} delay={p.delay} color={p.color} />
        ))}
        {strikeStyle && (
          <StrikeLine
            x1={0} y1={0} x2={0} y2={0}
            color={strikeColor}
            style={strikeStyle}
          />
        )}
        <Grid>
          {board.map((cell, i) => (
            <Cell
              key={i}
              isWinning={winningSet.has(i)}
              isThinking={isBotThinking && !cell}
              disabled={!!cell || gameOver || (mode === 'bot' && !isPlayerTurn)}
              onClick={() => handleCellClick(i)}
              aria-label={`Cell ${Math.floor(i / 3) + 1},${(i % 3) + 1}${cell ? `: ${cell}` : ''}`}
            >
              {cell && (
                <CellContent isNew={i === lastPlaced}>
                  {cellEmoji(cell)}
                </CellContent>
              )}
            </Cell>
          ))}
        </Grid>
      </BoardContainer>

      {mode === 'bot' && (
        <ScoreBoard>
          <ScoreItem color="#3fb950">
            <ScoreValue color="#3fb950" pop={poppedScore === 'wins'}>{score.wins}</ScoreValue>
            <ScoreLabel>{t('wins')}</ScoreLabel>
          </ScoreItem>
          <ScoreItem color="#d2a922">
            <ScoreValue color="#d2a922" pop={poppedScore === 'draws'}>{score.draws}</ScoreValue>
            <ScoreLabel>{t('draws')}</ScoreLabel>
          </ScoreItem>
          <ScoreItem color="#f97583">
            <ScoreValue color="#f97583" pop={poppedScore === 'losses'}>{score.losses}</ScoreValue>
            <ScoreLabel>{t('losses')}</ScoreLabel>
          </ScoreItem>
        </ScoreBoard>
      )}

      {gameOver && (
        <Actions>
          <Btn variant="primary" onClick={resetGame}>{t('playAgain')}</Btn>
        </Actions>
      )}
    </Wrapper>
  );
}
