// ─── Types ───────────────────────────────────────────────────────────────────

interface SoundHunterProps {
  lang: string;
  onBack: () => void;
}

interface Mission {
  id: string;
  emoji: string;
  en: string;
  pt: string;
}

interface MissionState {
  recording: boolean;
  audioUrl: string | null;
  completed: boolean;
  timerSecs: number;
}

type MissionStateMap = Record<string, MissionState>;

