// ─── Mission card ─────────────────────────────────────────────────────────────

interface MissionCardProps {
  mission: Mission;
  state: MissionState;
  lang: string;
  justCompleted: boolean;
  onRecord: () => void;
  onStop: () => void;
  onPlay: () => void;
  onComplete: () => void;
  permError: string | null;
}

function MissionCard({
  mission,
  state,
  lang,
  justCompleted,
  onRecord,
  onStop,
  onPlay,
  onComplete,
  permError,
}: MissionCardProps) {
  const label = lang === 'pt' ? mission.pt : mission.en;

  return (
    <Card completed={state.completed} recording={state.recording} justCompleted={justCompleted}>
      <MissionEmoji>{mission.emoji}</MissionEmoji>
      <MissionLabel>{label}</MissionLabel>

      {state.completed ? (
        <CompletedBadge>
          <StarIcon>⭐</StarIcon> {t('complete', lang)}
        </CompletedBadge>
      ) : (
        <>
          <RecordRow>
            {state.recording ? (
              <>
                <WaveBars />
                <TimerBadge>{MAX_RECORD_SECS - state.timerSecs}s</TimerBadge>
                <Btn variant="danger" onClick={onStop}>
                  ⏹ {t('stop', lang)}
                </Btn>
              </>
            ) : (
              <Btn variant="primary" className="record-btn" onClick={onRecord}>
                🎙 {t('record', lang)}
              </Btn>
            )}

            {state.audioUrl && !state.recording && (
              <Btn variant="ghost" onClick={onPlay}>
                ▶ {t('play', lang)}
              </Btn>
            )}
          </RecordRow>

          <RecordingHint>
            {state.recording
              ? t('recording', lang)
              : state.audioUrl
              ? ''
              : t('tapRecord', lang)}
          </RecordingHint>

          {permError && <PermError>{permError}</PermError>}

          {state.audioUrl && !state.recording && (
            <Btn variant="success" onClick={onComplete}>
              ✅ {t('markDone', lang)}
            </Btn>
          )}
        </>
      )}
    </Card>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

const MILESTONES = [25, 50, 75];

export function SoundHunter({ lang, onBack }: SoundHunterProps) {
  const [missionStates, setMissionStates] = useState<MissionStateMap>(() => {
    const base = defaultState();
    const completed = loadProgress();
    for (const id of completed) {
      if (base[id]) base[id] = { ...base[id], completed: true };
    }
    return base;
  });

  const [permErrors, setPermErrors] = useState<Record<string, string>>({});
  const [justCompletedIds, setJustCompletedIds] = useState<Set<string>>(new Set());
  const [flashingMilestone, setFlashingMilestone] = useState<number | null>(null);
  const prevPctRef = useRef(0);

  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<BlobPart[]>([]);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const activeIdRef = useRef<string | null>(null);

  const completedCount = Object.values(missionStates).filter((s) => s.completed).length;
  const allDone = completedCount === MISSIONS.length;
  const pct = Math.round((completedCount / MISSIONS.length) * 100);

  // Detect milestone crossing
  useEffect(() => {
    const prevPct = prevPctRef.current;
    for (const m of MILESTONES) {
      if (prevPct < m && pct >= m) {
        setFlashingMilestone(m);
        setTimeout(() => setFlashingMilestone(null), 1800);
        break;
      }
    }
    prevPctRef.current = pct;
  }, [pct]);

  // Persist completed set whenever it changes
  useEffect(() => {
    const ids = new Set(
      Object.entries(missionStates)
        .filter(([, s]) => s.completed)
        .map(([id]) => id),
    );
    saveProgress(ids);
  }, [missionStates]);

  const updateState = useCallback(
    (id: string, patch: Partial<MissionState>) => {
      setMissionStates((prev) => ({
        ...prev,
        [id]: { ...prev[id], ...patch },
      }));
    },
    [],
  );

  const stopTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const stopRecording = useCallback(
    (id: string) => {
      stopTimer();
      if (recorderRef.current && recorderRef.current.state !== 'inactive') {
        recorderRef.current.stop();
      }
      updateState(id, { recording: false, timerSecs: 0 });
      activeIdRef.current = null;
    },
    [stopTimer, updateState],
  );

  const handleRecord = useCallback(
    async (id: string) => {
      // Stop any active recording first
      if (activeIdRef.current && activeIdRef.current !== id) {
        stopRecording(activeIdRef.current);
      }

      setPermErrors((prev) => ({ ...prev, [id]: '' }));

      let stream: MediaStream;
      try {
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      } catch (err) {
        const msg =
          err instanceof DOMException && err.name === 'NotAllowedError'
            ? t('permDenied', lang)
            : t('permError', lang);
        setPermErrors((prev) => ({ ...prev, [id]: msg }));
        return;
      }

      chunksRef.current = [];
      const recorder = new MediaRecorder(stream);
      recorderRef.current = recorder;
      activeIdRef.current = id;

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      recorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
        const url = URL.createObjectURL(blob);
        updateState(id, { audioUrl: url });
        stream.getTracks().forEach((track) => track.stop());
      };

      recorder.start();
      updateState(id, { recording: true, timerSecs: 0 });

      let elapsed = 0;
      timerRef.current = setInterval(() => {
        elapsed += 1;
        updateState(id, { timerSecs: elapsed });
        if (elapsed >= MAX_RECORD_SECS) {
          stopRecording(id);
        }
      }, 1000);
    },
    [lang, stopRecording, updateState],
  );

  const handleStop = useCallback(
    (id: string) => {
      stopRecording(id);
    },
    [stopRecording],
  );

  const handlePlay = useCallback((id: string) => {
    const url = missionStates[id]?.audioUrl;
    if (!url) return;
    const audio = new Audio(url);
    audio.play().catch(() => {
      // Ignore autoplay errors silently
    });
  }, [missionStates]);

  const handleComplete = useCallback(
    (id: string) => {
      updateState(id, { completed: true });
      setJustCompletedIds((prev) => new Set([...prev, id]));
      // Clear the justCompleted flag after animation finishes
      setTimeout(() => {
        setJustCompletedIds((prev) => {
          const next = new Set(prev);
          next.delete(id);
          return next;
        });
      }, 1600);
    },
    [updateState],
  );

  const handleReset = useCallback(() => {
    // Revoke any object URLs to free memory
    Object.values(missionStates).forEach((s) => {
      if (s.audioUrl) URL.revokeObjectURL(s.audioUrl);
    });
    stopTimer();
    if (recorderRef.current && recorderRef.current.state !== 'inactive') {
      recorderRef.current.stop();
    }
    activeIdRef.current = null;
    setMissionStates(defaultState());
    setPermErrors({});
    setJustCompletedIds(new Set());
    setFlashingMilestone(null);
    prevPctRef.current = 0;
    localStorage.removeItem(STORAGE_KEY);
  }, [missionStates, stopTimer]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopTimer();
      if (recorderRef.current && recorderRef.current.state !== 'inactive') {
        recorderRef.current.stop();
      }
      Object.values(missionStates).forEach((s) => {
        if (s.audioUrl) URL.revokeObjectURL(s.audioUrl);
      });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (allDone) {
    return (
      <Wrapper>
        <Confetti />
        <CelebrateWrapper>
          <TrophyWrapper>🏆</TrophyWrapper>
          <CelebrateTitle>{t('celebrate', lang)}</CelebrateTitle>
          <CelebrateSub>{t('celebrateSub', lang)}</CelebrateSub>
          <RecordRow>
            <Btn variant="primary" onClick={handleReset}>
              🔄 {t('celebrateReset', lang)}
            </Btn>
          </RecordRow>
        </CelebrateWrapper>
      </Wrapper>
    );
  }

  return (
    <Wrapper>
      <Header>
        <Title>🎙 {t('title', lang)}</Title>
        <Subtitle>{t('subtitle', lang)}</Subtitle>
      </Header>

      <ProgressSection>
        <ProgressLabel>
          <span>{t('progress', lang)}</span>
          <ProgressCount>
            {completedCount} / {MISSIONS.length}
          </ProgressCount>
        </ProgressLabel>
        <ProgressBarTrack>
          <ProgressBarInner>
            <ProgressBarFill pct={pct} />
          </ProgressBarInner>
          {MILESTONES.map((m) => (
            <MilestoneDot
              key={m}
              position={m}
              reached={pct >= m}
              flashing={flashingMilestone === m}
            />
          ))}
        </ProgressBarTrack>
      </ProgressSection>

      <Grid>
        {MISSIONS.map((mission) => (
          <MissionCard
            key={mission.id}
            mission={mission}
            state={missionStates[mission.id]}
            lang={lang}
            justCompleted={justCompletedIds.has(mission.id)}
            onRecord={() => handleRecord(mission.id)}
            onStop={() => handleStop(mission.id)}
            onPlay={() => handlePlay(mission.id)}
            onComplete={() => handleComplete(mission.id)}
            permError={permErrors[mission.id] ?? null}
          />
        ))}
      </Grid>

      <Footer>
        <Btn variant="ghost" onClick={handleReset}>
          🔄 {t('reset', lang)}
        </Btn>
      </Footer>
    </Wrapper>
  );
}
