// ─── Component ────────────────────────────────────────────────────────────────

const MAX_HISTORY = 20;

export function PixelBoard({ lang, onBack }: PixelBoardProps) {
  const t = useCallback((key: string) => LABELS[key]?.[lang] ?? LABELS[key]?.en ?? key, [lang]);

  const [gridSize, setGridSize] = useState<GridSize>(12);
  const [grid, setGrid] = useState<string[]>(() => makeEmptyGrid(12));
  const [history, setHistory] = useState<string[][]>([]);
  const [selectedColor, setSelectedColor] = useState<string>(PALETTE[0]);
  const [tool, setTool] = useState<Tool>('paint');
  const [newCellIdx, setNewCellIdx] = useState<number | null>(null);
  const [isPainting, setIsPainting] = useState(false);
  const [gallery, setGallery] = useState<SavedDrawing[]>(() => loadGallery());
  const [view, setView] = useState<'draw' | 'gallery'>('draw');
  const [showConfirmClear, setShowConfirmClear] = useState(false);
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const [savedFlash, setSavedFlash] = useState(false);
  const [saveName, setSaveName] = useState('');
  const [hasEverPainted, setHasEverPainted] = useState(false);

  const isEmpty = useMemo(() => grid.every((c) => c === ''), [grid]);

  // Touch tracking: position at touchstart
  const touchStartRef = useRef<{ x: number; y: number; idx: number } | null>(null);
  const gridRef = useRef<HTMLDivElement | null>(null);
  const popTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Flash animation cleanup
  const flashCell = useCallback((idx: number) => {
    setNewCellIdx(idx);
    if (popTimerRef.current) clearTimeout(popTimerRef.current);
    popTimerRef.current = setTimeout(() => setNewCellIdx(null), 200);
  }, []);

  // Push current grid to undo history
  const pushHistory = useCallback((snapshot: string[]) => {
    setHistory((prev) => [...prev.slice(-MAX_HISTORY + 1), snapshot]);
  }, []);

  const paintCell = useCallback((idx: number) => {
    setGrid((prev) => {
      const color = tool === 'eraser' ? '' : selectedColor;
      if (prev[idx] === color) return prev;
      pushHistory(prev);
      const next = [...prev];
      next[idx] = color;
      return next;
    });
    setHasEverPainted(true);
    flashCell(idx);
  }, [tool, selectedColor, flashCell, pushHistory]);

  // Undo
  const handleUndo = useCallback(() => {
    setHistory((prev) => {
      if (prev.length === 0) return prev;
      const snapshot = prev[prev.length - 1];
      setGrid(snapshot);
      return prev.slice(0, -1);
    });
  }, []);

  // Mouse events
  const handleMouseDown = useCallback((idx: number) => {
    setIsPainting(true);
    paintCell(idx);
  }, [paintCell]);

  const handleMouseEnter = useCallback((idx: number) => {
    if (isPainting) paintCell(idx);
  }, [isPainting, paintCell]);

  const handleMouseUp = useCallback(() => {
    setIsPainting(false);
  }, []);

  useEffect(() => {
    const stop = () => setIsPainting(false);
    window.addEventListener('mouseup', stop);
    return () => window.removeEventListener('mouseup', stop);
  }, []);

  // Touch events — no preventDefault on touchstart
  const getCellIdxFromPoint = useCallback((clientX: number, clientY: number): number | null => {
    if (!gridRef.current) return null;
    const rect = gridRef.current.getBoundingClientRect();
    const x = clientX - rect.left;
    const y = clientY - rect.top;
    if (x < 0 || y < 0 || x > rect.width || y > rect.height) return null;
    const col = Math.floor((x / rect.width) * gridSize);
    const row = Math.floor((y / rect.height) * gridSize);
    if (col < 0 || col >= gridSize || row < 0 || row >= gridSize) return null;
    return row * gridSize + col;
  }, [gridSize]);

  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    const touch = e.touches[0];
    const idx = getCellIdxFromPoint(touch.clientX, touch.clientY);
    touchStartRef.current = {
      x: touch.clientX,
      y: touch.clientY,
      idx: idx ?? -1,
    };
  }, [getCellIdxFromPoint]);

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (!touchStartRef.current) return;
    const touch = e.changedTouches[0];
    const dx = Math.abs(touch.clientX - touchStartRef.current.x);
    const dy = Math.abs(touch.clientY - touchStartRef.current.y);
    // If movement is large, this is a scroll — do not paint, let it scroll
    if (dx > 8 || dy > 8) {
      // Only paint if it looks like deliberate drag across cells (dx dominant over dy)
      if (dx > dy * 2 || dy <= 8) {
        // horizontal drag — paint
        const idx = getCellIdxFromPoint(touch.clientX, touch.clientY);
        if (idx !== null) paintCell(idx);
      }
      // else vertical scroll — do nothing
      return;
    }
  }, [getCellIdxFromPoint, paintCell]);

  const handleTouchEnd = useCallback((e: React.TouchEvent) => {
    if (!touchStartRef.current) return;
    const touch = e.changedTouches[0];
    const dx = Math.abs(touch.clientX - touchStartRef.current.x);
    const dy = Math.abs(touch.clientY - touchStartRef.current.y);
    const startIdx = touchStartRef.current.idx;
    touchStartRef.current = null;
    // If small movement (tap) — paint the cell
    if (dx <= 8 && dy <= 8 && startIdx >= 0) {
      paintCell(startIdx);
    }
  }, [paintCell]);

  // Grid size change
  const handleSizeChange = useCallback((size: GridSize) => {
    setGridSize(size);
    setGrid(makeEmptyGrid(size));
    setHistory([]);
    setHasEverPainted(false);
  }, []);

  // Tool change
  const handleToolChange = useCallback((newTool: Tool) => {
    setTool(newTool);
  }, []);

  // Clear
  const handleClearConfirm = useCallback(() => {
    pushHistory(grid);
    setGrid(makeEmptyGrid(gridSize));
    setShowConfirmClear(false);
    setHasEverPainted(false);
  }, [gridSize, grid, pushHistory]);

  // Save
  const openSaveDialog = useCallback(() => {
    setSaveName(t('myDrawing'));
    setShowSaveDialog(true);
  }, [t]);

  const handleSave = useCallback(() => {
    const name = saveName.trim() || t('myDrawing');
    const drawing: SavedDrawing = {
      id: Date.now().toString(),
      name,
      grid: [...grid],
      size: gridSize,
      savedAt: Date.now(),
    };
    const updated = [drawing, ...gallery].slice(0, 30);
    setGallery(updated);
    saveGallery(updated);
    setShowSaveDialog(false);
    setSavedFlash(true);
    setTimeout(() => setSavedFlash(false), 1800);
  }, [saveName, grid, gridSize, gallery, t]);

  // Gallery load/delete
  const handleLoadDrawing = useCallback((drawing: SavedDrawing) => {
    setGridSize(drawing.size);
    setGrid(drawing.grid);
    setHistory([]);
    setHasEverPainted(true);
    setView('draw');
  }, []);

  const handleDeleteDrawing = useCallback((id: string) => {
    const updated = gallery.filter((d) => d.id !== id);
    setGallery(updated);
    saveGallery(updated);
  }, [gallery]);

  // Templates
  const loadTemplate = useCallback((tplFn: (size: GridSize) => string[]) => {
    pushHistory(grid);
    setGrid(tplFn(gridSize));
    setHasEverPainted(true);
  }, [gridSize, grid, pushHistory]);

  // Pre-compute template previews at size 8 for thumbnails
  const templatePreviews = useMemo(() => ({
    heart: getHeartTemplate(8),
    star: getStarTemplate(8),
    smiley: getSmileyTemplate(8),
  }), []);

  // ─── Render: Gallery ───────────────────────────────────────────────────────
  if (view === 'gallery') {
    return (
      <Wrapper>
        <TitleRow>
          <ToolBtn onClick={() => setView('draw')}>← {t('close')}</ToolBtn>
          <SectionTitle>🖼️ {t('gallery')}</SectionTitle>
        </TitleRow>
        <DialogOverlay>
          {gallery.length === 0 ? (
            <EmptyText>{t('emptyGallery')}</EmptyText>
          ) : (
            <GalleryGrid>
              {gallery.map((drawing) => (
                <GalleryCard key={drawing.id}>
                  <GalleryThumb cols={drawing.size}>
                    {drawing.grid.map((color, i) => (
                      <ThumbCell key={i} color={color} />
                    ))}
                  </GalleryThumb>
                  <GalleryCardFooter>
                    <GalleryCardName>{drawing.name}</GalleryCardName>
                    <GalleryActions>
                      <SmallBtn variant="primary" onClick={() => handleLoadDrawing(drawing)}>
                        {t('load')}
                      </SmallBtn>
                      <SmallBtn variant="danger" onClick={() => handleDeleteDrawing(drawing.id)}>
                        {t('delete')}
                      </SmallBtn>
                    </GalleryActions>
                  </GalleryCardFooter>
                </GalleryCard>
              ))}
            </GalleryGrid>
          )}
        </DialogOverlay>
      </Wrapper>
    );
  }

  // ─── Render: Main Draw View ────────────────────────────────────────────────
  return (
    <Wrapper>
      {/* Confirm Clear Overlay */}
      {showConfirmClear && (
        <ModalBackdrop onClick={() => setShowConfirmClear(false)}>
          <ConfirmOverlay onClick={(e) => e.stopPropagation()}>
            <ConfirmText>{t('confirmClear')}</ConfirmText>
            <ConfirmActions>
              <ToolBtn onClick={() => setShowConfirmClear(false)}>{t('no')}</ToolBtn>
              <ToolBtn danger onClick={handleClearConfirm}>{t('yes')}</ToolBtn>
            </ConfirmActions>
          </ConfirmOverlay>
        </ModalBackdrop>
      )}

      {/* Save Dialog Overlay */}
      {showSaveDialog && (
        <ModalBackdrop onClick={() => setShowSaveDialog(false)}>
          <ConfirmOverlay onClick={(e) => e.stopPropagation()}>
            <ConfirmText>{t('drawingName')}</ConfirmText>
            <input
              value={saveName}
              onChange={(e) => setSaveName(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') handleSave(); if (e.key === 'Escape') setShowSaveDialog(false); }}
              autoFocus
              style={{
                background: theme.colors.mainBg,
                border: `1px solid ${theme.colors.border}`,
                borderRadius: theme.borderRadius.md,
                color: theme.colors.mainText,
                padding: '8px 12px',
                fontSize: theme.typography.fontSizeBase,
                fontFamily: theme.typography.fontFamily,
                width: '100%',
                outline: 'none',
              }}
            />
            <ConfirmActions>
              <ToolBtn onClick={() => setShowSaveDialog(false)}>{t('no')}</ToolBtn>
              <ToolBtn onClick={handleSave}>{t('save')} 💾</ToolBtn>
            </ConfirmActions>
          </ConfirmOverlay>
        </ModalBackdrop>
      )}

      <TitleRow>
        <Title>🎨 {t('title')}</Title>
      </TitleRow>

      <ControlsRow>
        {/* Row 1: Undo + Tool toggle + Size */}
        <ToolRow>
          <IconOnlyBtn
            onClick={handleUndo}
            disabled={history.length === 0}
            aria-label={t('undo')}
            title={t('undo')}
          >
            ↩️
          </IconOnlyBtn>
          <ToolBtn active={tool === 'paint'} onClick={() => handleToolChange('paint')}>
            🎨 {t('paint')}
          </ToolBtn>
          <ToolBtn active={tool === 'eraser'} onClick={() => handleToolChange('eraser')}>
            🧹 {t('eraser')}
          </ToolBtn>
          <SizeBar>
            {GRID_SIZES.map((s) => (
              <SizeBtn key={s} active={gridSize === s} onClick={() => handleSizeChange(s)}>
                {s}×{s}
              </SizeBtn>
            ))}
          </SizeBar>
        </ToolRow>

        {/* Row 2: Actions */}
        <ToolRow>
          <IconOnlyBtn danger onClick={() => setShowConfirmClear(true)} title={t('clearAll')} aria-label={t('clearAll')}>
            🗑️
          </IconOnlyBtn>
          <IconOnlyBtn onClick={openSaveDialog} title={t('save')} aria-label={t('save')}>
            💾
          </IconOnlyBtn>
          <ToolBtn onClick={() => setView('gallery')}>
            🖼️ {t('gallery')} {gallery.length > 0 && `(${gallery.length})`}
          </ToolBtn>
        </ToolRow>
      </ControlsRow>

      {/* Templates */}
      <TemplateRow>
        <span style={{ fontSize: 12, color: theme.colors.mainTextMuted, alignSelf: 'center', flexShrink: 0 }}>
          {t('templates')}:
        </span>
        <TemplateBtn onClick={() => loadTemplate(getHeartTemplate)}>
          <MiniGrid cols={8}>
            {templatePreviews.heart.map((color, i) => (
              <MiniCell key={i} color={color} />
            ))}
          </MiniGrid>
          {t('heart')}
        </TemplateBtn>
        <TemplateBtn onClick={() => loadTemplate(getStarTemplate)}>
          <MiniGrid cols={8}>
            {templatePreviews.star.map((color, i) => (
              <MiniCell key={i} color={color} />
            ))}
          </MiniGrid>
          {t('star')}
        </TemplateBtn>
        <TemplateBtn onClick={() => loadTemplate(getSmileyTemplate)}>
          <MiniGrid cols={8}>
            {templatePreviews.smiley.map((color, i) => (
              <MiniCell key={i} color={color} />
            ))}
          </MiniGrid>
          {t('smiley')}
        </TemplateBtn>
      </TemplateRow>

      {/* Pixel Grid */}
      <GridArea
        ref={gridRef}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      >
        <PixelGrid cols={gridSize} role="grid" aria-label={t('title')}>
          {grid.map((color, i) => (
            <PixelCell
              key={i}
              color={color}
              isNew={i === newCellIdx}
              role="gridcell"
              aria-label={`cell ${i}`}
              onMouseDown={() => handleMouseDown(i)}
              onMouseEnter={() => handleMouseEnter(i)}
              onMouseUp={handleMouseUp}
            />
          ))}
        </PixelGrid>
        {isEmpty && !hasEverPainted && (
          <CanvasHint>
            <HintText>{t('tapToPaint')}</HintText>
          </CanvasHint>
        )}
      </GridArea>

      {/* Color Palette */}
      <PaletteRow role="group" aria-label={t('selectedColor')}>
        {PALETTE.map((color) => (
          <ColorCircle
            key={color}
            color={color}
            selected={tool === 'paint' && selectedColor === color}
            onClick={() => { setSelectedColor(color); setTool('paint'); }}
            role="radio"
            aria-checked={tool === 'paint' && selectedColor === color}
            aria-label={color}
          />
        ))}
        <EraserCircle
          selected={tool === 'eraser'}
          onClick={() => setTool('eraser')}
          role="radio"
          aria-checked={tool === 'eraser'}
          aria-label={t('eraser')}
        >
          🧹
        </EraserCircle>
      </PaletteRow>

      {savedFlash && <SavedBadge>✅ {t('saved')}</SavedBadge>}

    </Wrapper>
  );
}
